import type { SandboxJson, SandboxSdk } from '@molis/plugin-sdk';
import { appendItem } from '../store.js';

/** 从调用输入里取出正文；拿不到字符串正文就是空。 */
function readText(input: SandboxJson): string | null {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) return null;
  const record = input as unknown as { [key: string]: SandboxJson };
  const value = record.text;
  return typeof value === 'string' ? value : null;
}

/**
 * items.add：把正文原样按调用顺序追加到当前项目安装的私有清单。
 * 不裁剪、不改写、不摘要、不去重；清单的键名约定见 src/store.ts。
 */
export default async function operation(input: SandboxJson, sdk: SandboxSdk): Promise<SandboxJson> {
  const text = readText(input);
  if (text === null || text.length === 0) {
    throw Object.assign(new Error('正文不能为空，新条目未写入清单'), { code: 'storage_write_failed' });
  }
  await appendItem(sdk, text);
  return { added: true };
}

