import type { SandboxJson, SandboxSdk } from '@molis/plugin-sdk';
import type { ItemEntry } from '../store.js';
import { readItems } from '../store.js';

/** 对外的一条清单条目：只有合同声明的三个字段。 */
type ListedItem = {
  id: string;
  text: string;
  created_at: string;
};

/** 读清单；读失败按合同唯一声明的错误码失败，不把底层错误原样抛出。 */
async function loadEntries(sdk: SandboxSdk): Promise<ItemEntry[]> {
  try {
    return await readItems(sdk);
  } catch {
    throw Object.assign(new Error('清单读取失败，请重试'), { code: 'storage_read_failed' });
  }
}

/** created_at 要是能读成时间的时间戳；旧数据里不是的就跳过。 */
function isDateTime(value: string): boolean {
  return value.length > 0 && Number.isFinite(Date.parse(value));
}

/**
 * items.list：按新增顺序读出当前项目安装的私有清单。
 * 清单的键名约定见 src/store.ts（`items` 是整份清单，`item:<id>` 是单条副本）。
 * 只返回合同声明的字段，正文原样给出，不裁剪、不改写、不去重。
 */
export default async function operation(_input: SandboxJson, sdk: SandboxSdk): Promise<SandboxJson> {
  const entries = await loadEntries(sdk);
  const items: ListedItem[] = [];
  for (const entry of entries) {
    if (!isDateTime(entry.created_at)) continue;
    items.push({ id: entry.id, text: entry.text, created_at: entry.created_at });
  }
  return { items };
}

