import type { SandboxJson, SandboxSdk } from '@molis/plugin-sdk';

/**
 * 本插件所有操作共用的私有存储约定（items.add 写入，items.list 读出）：
 * - `items`：按新增顺序保存整份清单，值是条目数组；
 * - `item:<id>`：同一条目的单条副本，键名是 `item:` + id。
 *
 * 条目就是清单对外的形状：{ id, text, created_at }。
 * text 原样保存（不裁剪、不改写、不摘要）；created_at 是 ISO 8601 时间；
 * id 由实现生成，写下后不再变化（升级、重启后仍是同一个 id）。
 */
export const ITEMS_KEY = 'items';
export const ITEM_PREFIX = 'item:';

export type ItemEntry = {
  id: string;
  text: string;
  created_at: string;
};

export function isItemEntry(value: SandboxJson): value is ItemEntry {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const record = value as unknown as { [key: string]: SandboxJson };
  return typeof record.id === 'string'
    && record.id.length > 0
    && typeof record.text === 'string'
    && typeof record.created_at === 'string'
    && record.created_at.length > 0;
}

/** 按新增顺序读出整份清单；没有清单时是空数组。 */
export async function readItems(sdk: SandboxSdk): Promise<ItemEntry[]> {
  const stored = await sdk.storage.get(ITEMS_KEY);
  if (!Array.isArray(stored)) return [];
  const entries: ItemEntry[] = [];
  for (const value of stored) {
    if (isItemEntry(value)) entries.push(value);
  }
  return entries;
}

/** 读清单失败时，add 也要按它唯一声明的错误码失败，不把读错误原样抛出去。 */
async function loadItems(sdk: SandboxSdk): Promise<ItemEntry[]> {
  try {
    return await readItems(sdk);
  } catch {
    throw Object.assign(new Error('无法读取当前清单，新条目未写入，请重试'), { code: 'storage_write_failed' });
  }
}

/** 新条目时间不早于上一条，顺序因此只取决于调用顺序。 */
function nextCreatedAt(previous: string | null): string {
  const now = Date.now();
  const previousMs = previous ? Date.parse(previous) : Number.NaN;
  const ms = Number.isFinite(previousMs) && now <= previousMs ? previousMs + 1 : now;
  return new Date(ms).toISOString();
}

/** id 里带时间戳，按 id 排序也就是按新增顺序。 */
function newId(createdAt: string): string {
  const stamp = createdAt.replace(/\D/g, '');
  const suffix = Math.random().toString(36).slice(2, 8);
  return 'i' + stamp + '-' + suffix;
}

/**
 * 把正文原样追加到清单末尾。
 * 先写单条副本再写整份清单：第二步失败时回滚刚写的副本，不留下半条记录。
 */
export async function appendItem(sdk: SandboxSdk, text: string): Promise<ItemEntry> {
  const entries = await loadItems(sdk);
  const last = entries.length > 0 ? entries[entries.length - 1] : null;
  const createdAt = nextCreatedAt(last ? last.created_at : null);
  const entry: ItemEntry = { id: newId(createdAt), text, created_at: createdAt };
  const next = entries.concat([entry]);
  let recordWritten = false;
  try {
    await sdk.storage.set(ITEM_PREFIX + entry.id, entry);
    recordWritten = true;
    await sdk.storage.set(ITEMS_KEY, next);
  } catch {
    if (recordWritten) {
      try {
        await sdk.storage.delete(ITEM_PREFIX + entry.id);
      } catch {
        // 回滚失败时不掩盖真正的写入错误
      }
    }
    throw Object.assign(new Error('清单写入失败，请重试'), { code: 'storage_write_failed' });
  }
  return entry;
}

