import type { SandboxJson, SandboxSdk, SandboxTest } from '@molis/plugin-sdk';

const SPACED = '  周三  预订会议室  ';
const MULTI_LINE = '先核对上周会议纪要。\n\n把待办按负责人分组，并标记今天必须完成的事项。\n\n最后确认会议室与投影设备；缺少的材料由我今晚补齐。';

/** 取第 n 条；缺条目就说明顺序不对，测试直接失败。 */
function at<T>(items: T[], index: number): T {
  const value = items[index];
  if (value === undefined) throw new Error('清单里缺少第 ' + (index + 1) + ' 条');
  return value;
}

/** 按新增顺序读出清单里的正文。 */
async function orderedTexts(sdk: SandboxSdk): Promise<string[]> {
  const stored = await sdk.storage.get('items');
  if (!Array.isArray(stored)) return [];
  const texts: string[] = [];
  for (const value of stored) {
    const entry = value as unknown as { text: string };
    texts.push(entry.text);
  }
  return texts;
}

/** 读出每条单条副本的正文。 */
async function recordTexts(sdk: SandboxSdk): Promise<string[]> {
  const records = await sdk.storage.list('item:');
  const texts: string[] = [];
  for (const record of records) {
    const entry = record.value as unknown as { text: string };
    texts.push(entry.text);
  }
  return texts;
}

/** 读出清单里的完整条目。 */
async function orderedEntries(sdk: SandboxSdk): Promise<Array<{ id: string; text: string; created_at: string }>> {
  const stored = await sdk.storage.get('items');
  if (!Array.isArray(stored)) return [];
  const entries: Array<{ id: string; text: string; created_at: string }> = [];
  for (const value of stored) {
    const entry = value as unknown as { id: string; text: string; created_at: string };
    entries.push(entry);
  }
  return entries;
}

export const tests: SandboxTest[] = [
  // 正常新增：返回值严格是 { added: true }，正文原样落库
  async (sdk, call, assert) => {
    const result = await call({ text: '周五整理资料' });
    assert.same(result, { added: true });

    const records = await sdk.storage.list('item:');
    assert.same(records.length, 1);
    const first = records[0];
    if (!first) throw new Error('没有找到刚写入的清单记录');
    const entry = first.value as unknown as { id: string; text: string; created_at: string };
    assert.same(entry.text, '周五整理资料');
    assert.same(entry.id.length > 0, true);
    assert.same(Number.isNaN(Date.parse(entry.created_at)), false);
    assert.same(first.key, 'item:' + entry.id);
    assert.same(await orderedTexts(sdk), ['周五整理资料']);
  },

  // 原样保存：首尾空格不动
  async (sdk, call, assert) => {
    const result = await call({ text: SPACED });
    assert.same(result, { added: true });
    assert.same(await orderedTexts(sdk), ['周五整理资料', SPACED]);
    assert.same(at(await recordTexts(sdk), 1), SPACED);
  },

  // 原样保存：换行和标点不动
  async (sdk, call, assert) => {
    const result = await call({ text: MULTI_LINE });
    assert.same(result, { added: true });
    assert.same(at(await orderedTexts(sdk), 2), MULTI_LINE);
    assert.same(at(await recordTexts(sdk), 2), MULTI_LINE);
  },

  // 不去重：相同正文重复追加，各自成为一条
  async (sdk, call, assert) => {
    await call({ text: '周五整理资料' });
    await call({ text: '周五整理资料' });
    assert.same(await orderedTexts(sdk), ['周五整理资料', SPACED, MULTI_LINE, '周五整理资料', '周五整理资料']);
    assert.same((await recordTexts(sdk)).length, 5);
  },

  // 追加顺序与条目形状：id 唯一、created_at 递增、正文与调用一致
  async (sdk, call, assert) => {
    const entries = await orderedEntries(sdk);
    assert.same(entries.length, 5);
    const ids = entries.map((entry) => entry.id);
    assert.same(new Set(ids).size, 5);
    const times = entries.map((entry) => entry.created_at);
    assert.same(times.every((time, index) => index === 0 || time > at(times, index - 1)), true);
    assert.same(entries.map((entry) => entry.text), ['周五整理资料', SPACED, MULTI_LINE, '周五整理资料', '周五整理资料']);
    for (const entry of entries) {
      const record = await sdk.storage.get('item:' + entry.id);
      assert.same(record, entry);
    }
  },

  // 写入失败：按合同错误码失败，且不留下半条记录
  async (sdk, call, assert) => {
    const originalSet = sdk.storage.set.bind(sdk.storage);
    sdk.storage.set = async () => {
      throw new Error('storage unavailable');
    };
    try {
      await assert.rejectsCode(() => call({ text: '写不进去的正文' }), 'storage_write_failed');
    } finally {
      sdk.storage.set = originalSet;
    }
    assert.same(await orderedTexts(sdk), ['周五整理资料', SPACED, MULTI_LINE, '周五整理资料', '周五整理资料']);
    assert.same((await recordTexts(sdk)).includes('写不进去的正文'), false);
  },

  // 空正文：不写入清单
  async (sdk, call, assert) => {
    await assert.rejectsCode(() => call({ text: '' }), 'storage_write_failed');
    assert.same((await orderedTexts(sdk)).length, 5);
    assert.same((await recordTexts(sdk)).length, 5);
  },
];

