import type { SandboxTest } from '@molis/plugin-sdk';

const FIRST = { id: 'i001', text: '周五整理资料', created_at: '2026-01-02T03:04:05.000Z' };
const SECOND = { id: 'i002', text: '  周三  预订会议室  ', created_at: '2026-01-02T03:04:06.000Z' };
const THIRD = { id: 'i003', text: '周五整理资料', created_at: '2026-01-02T03:04:07.000Z' };

type ListedItem = { id: string; text: string; created_at: string };

/** 从结果里取出清单；结果形状不对就让测试直接失败。 */
function itemsOf(result: unknown): ListedItem[] {
  if (typeof result !== 'object' || result === null) throw new Error('结果不是对象');
  const record = result as { items?: unknown };
  if (!Array.isArray(record.items)) throw new Error('结果里没有 items 数组');
  return record.items as ListedItem[];
}

export const tests: SandboxTest[] = [
  // 空安装：完整结果严格等于 { items: [] }
  async (sdk, call, assert) => {
    const result = await call({});
    assert.same(result, { items: [] });
  },

  // 有条目：按新增顺序返回，重复正文不去重，正文原样
  async (sdk, call, assert) => {
    await sdk.storage.set('items', [FIRST, SECOND, THIRD]);
    const result = await call({});
    assert.same(result, { items: [FIRST, SECOND, THIRD] });
  },

  // 条目形状严格：每条只有 id、text、created_at
  async (sdk, call, assert) => {
    await sdk.storage.set('items', [FIRST, SECOND]);
    const items = itemsOf(await call({}));
    assert.same(items.length, 2);
    for (const item of items) {
      assert.same(Object.keys(item).sort(), ['created_at', 'id', 'text']);
      assert.same(item.id.length > 0, true);
      assert.same(Number.isNaN(Date.parse(item.created_at)), false);
    }
    assert.same(
      items.map((item) => item.text),
      ['周五整理资料', '  周三  预订会议室  '],
    );
  },

  // 读取失败：按合同错误码失败
  async (sdk, call, assert) => {
    await sdk.storage.set('items', [FIRST]);
    const originalGet = sdk.storage.get.bind(sdk.storage);
    sdk.storage.get = async () => {
      throw new Error('storage unavailable');
    };
    try {
      await assert.rejectsCode(() => call({}), 'storage_read_failed');
    } finally {
      sdk.storage.get = originalGet;
    }
  },

  // 旧数据缺字段：坏条目被跳过，其余条目照常返回
  async (sdk, call, assert) => {
    await sdk.storage.set('items', [{ id: 'i000', text: '缺时间戳的旧条目' }, FIRST]);
    const result = await call({});
    assert.same(result, { items: [FIRST] });
  },

  // 读取失败后重试：恢复读取就恢复结果
  async (sdk, call, assert) => {
    await sdk.storage.set('items', [FIRST, SECOND]);
    const originalGet = sdk.storage.get.bind(sdk.storage);
    sdk.storage.get = async () => {
      throw new Error('storage unavailable');
    };
    try {
      await assert.rejectsCode(() => call({}), 'storage_read_failed');
    } finally {
      sdk.storage.get = originalGet;
    }
    const result = await call({});
    assert.same(result, { items: [FIRST, SECOND] });
  },
];
